import{_ as a,c as t,o as p,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"佚　文","description":"橫渠易說 - 佚　文","frontmatter":{"title":"佚　文","description":"橫渠易說 - 佚　文"},"headers":[],"relativePath":"classics/hengqu/002.md","filePath":"classics/hengqu/002.md"}'),r={name:"classics/hengqu/002.md"};function n(c,e,_,i,o,l){return p(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="佚-文" tabindex="-1">佚　文 <a class="header-anchor" href="#佚-文" aria-label="Permalink to “佚　文”">​</a></h1><p>四庫書目提要稱此書末“有總論十一則”，即指下列諸文，後人因亦以總論稱之。然細審原文，大抵皆集零簡斷片而成，且可分為二十四則。其中僅四則可視為繫辭總論，餘皆為《易說》或《理窟》、語錄之錯簡，而見於精義者尤為不少。此蓋編集《易說》時發見之佚文，以其無可歸納，附之於末。今分別移入有關各文之下，並逐條註明。</p><p>繫辭所舉易義是聖人議論到此，因舉易義以成之，亦是人道之大且要者也。繫辭反覆惟在明易所以為易，撮聚眾意以為解，欲曉後人也。化不可言，難知可以言；難見如日景之行，則可知之；其所以行，則難見也。人於龜策無情之物，不知其將如何，惟是自然莫或使之然者，陰陽不測之類也。己方虛心以鄉之，卦成於爻以佔之，其辭如何，取以為佔。聖人則又於陰陽不測處以為佔，或於夢寐或於人事卜之，然聖人於卜筮亦鮮，蓋其為疑少故也。</p><p>不見《易》則不識造化，不識造化則不知性命。既不識造化，則將何謂之性命也？《大易》不言有無，諸子之陋也。人雖信此說，然不知能以何為有，以何謂之無。如人之言曰自然，而鮮有識自然之為體。觀其幾者，善之幾也。惡不可謂之幾。如曰幾者，動之微，吉之先見，亦止言吉耳。上交不諂，下交不瀆，人事不過於上下之交，此可盡人道也。且如孝弟，仁之本，亦可以言幾。造端乎夫婦，亦可以言幾。親親而尊賢，亦可以為幾。就親親尊賢而求之，又有幾焉。又如言不誠其身，不悅於親，亦是幾處。苟要入德，必始於知幾。</p><p>欲觀《易》，先當玩辭，蓋所以說《易》象也。不先盡繫辭，則其觀於《易》也或遠或近，或太艱難。不知繫辭而求《易》正，猶不知禮而□□秋也。繫辭所以論《易》之道，既知《易》之道，則《易》象在其中。故觀《易》必由繫辭。繫辭獨說九卦之德者，蓋九卦為德切於人事。有謂心即是《易》，造化也。心又焉能盡《易》之道？《易》象系之以辭者，於卦既已具其意象矣，又切於人事言之以示勸戒。釋氏之言性，不識《易》；識《易》然後儘性。蓋《易》則有無動靜，可以兼而不偏舉也。無則氣自然生，氣之生即是道，是《易》。</p><p>乾不居正位，是乾理自然，惟人推之使然邪。</p><p>主應物不能固知，此行而流也。入德處不移，則是道不進，重滯者也。</p><p>動靜不失其時，是時措之宜也，集義也。集義久則自有光明。靜則無見，必動乃見其道光明，以其本之光明故，其發也光明。學行之乃見，至其疑處始是實疑。於是有學，險而止，蒙。夫於不當止而止，是險也。如告子之不動心，必以義為外，是險而止也。蒙險在內，是矇昧之義。蒙方始務求學，而得之始是得所止也。若蹇則是險在外者也。</p><p>《易》乃是性與天道，其字日月為《易》。《易》之義包天道變化。</p><p>《易》非止數，《春秋》大義不止在元。</p><p>在《易》則是至理，在孟子則是氣。</p>',11)])])}const h=a(r,[["render",n]]);export{f as __pageData,h as default};
